import subprocess, itertools
def run(flags,pat,rep,inp):
    p=subprocess.run(["./executable","-f",flags,pat,rep],input=inp,capture_output=True)
    return p.stdout
def props(flags):
    m = run(flags,"^b","X",b"a\nb\n")==b"a\nX\n"
    i = run(flags,"foo","X",b"FOO\n")==b"X\n"
    s = run(flags,"a.b","X",b"a\nb\n")==b"X\n"
    w = run(flags,"foo","X",b"foobar foo\n")==b"foobar X\n"
    return (m,i,s,w)
alpha="ceimsw"
results={}
for l in range(4):
    for tup in itertools.product(alpha,repeat=l):
        f="".join(tup)
        results[f]=props(f)
# Analyze M
print("strings where M=1:")
for f,v in results.items():
    if v[0]: print(f,v)
print("--- count",sum(v[0] for v in results.values()),"/",len(results))
# save
import json,sys
json.dump({k:v for k,v in results.items()}, open("/tmp/flagprops.json","w"))
PY"}

