import json
res={k:tuple(v) for k,v in json.load(open("/tmp/flagprops.json")).items()}
def last_ic(f):
    # after last w?
    return None
# Hypothesis I: consider substring after last w (if any); I = (last among i/c in that substring == i)
def predI(f):
    seg=f.rsplit('w',1)[-1] if 'w' in f else f
    last=None
    for ch in seg:
        if ch in 'ic': last=ch
    return last=='i'
def predS(f):
    seg=f.rsplit('w',1)[-1] if 'w' in f else f
    return 's' in seg
def predW(f):
    return 'w' in f
def predM(f):
    return ('e' not in f) and ('w' not in f) and (('s' not in f) or ('m' in f))
bad=[]
for f,v in res.items():
    p=(predM(f),predI(f),predS(f),predW(f))
    if p!=v:
        bad.append((f,v,p))
print("mismatches",len(bad))
for b in bad[:50]: print(b)
# Also check I rule without w segmentation alternative: i after last c (?) etc
PY"}

