cat > vendor/terminal_size/src/lib.rs <<'RS'
//! A tiny terminal-size implementation for Unix-like systems.
//!
//! clap's `wrap_help` support only needs [`terminal_size`]. The two public
//! tuple types mirror the interface it expects.

/// Terminal width in columns.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Height(pub u16);

fn size_of_fd<F>(fd: F) -> Option<(Width, Height)>
where
    F: std::os::fd::AsFd,
{
    let winsize = rustix::termios::tcgetwinsize(fd).ok()?;
    if winsize.ws_col == 0 || winsize.ws_row == 0 {
        return None;
    }
    Some((Width(winsize.ws_col), Height(winsize.ws_row)))
}

/// Returns the size of the terminal attached to standard output, standard
/// error, or standard input, in that order.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(std::io::stdout())
        .or_else(|| size_of_fd(std::io::stderr()))
        .or_else(|| size_of_fd(std::io::stdin()))
}
RS
