// ---------------------------------------------------------------------------
// Replacement-string validation and unescaping
// ---------------------------------------------------------------------------

fn is_capture_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// Rejects a replacement such as `$1x`, where a numbered capture is directly
/// followed by further capture-name characters. Without braces the regex
/// replacement parser would read `1x` as a (non-existent) capture name.
fn validate_replacement(replacement: &str) -> Outcome<()> {
    let chars: Vec<char> = replacement.chars().collect();
    let mut index = 0;

    while index < chars.len() {
        if chars[index] != '$' {
            index += 1;
            continue;
        }

        // `$$` is an escaped literal dollar.
        if index + 1 < chars.len() && chars[index + 1] == '$' {
            index += 2;
            continue;
        }

        // `${...}` is unambiguous. A `${` without a closing brace is not a
        // capture reference, so scanning simply moves past the dollar.
        if index + 1 < chars.len() && chars[index + 1] == '{' {
            if let Some(offset) = chars[index + 2..].iter().position(|&c| c == '}') {
                index += 2 + offset + 1;
            } else {
                index += 1;
            }
            continue;
        }

        let name_start = index + 1;
        let mut name_end = name_start;
        while name_end < chars.len() && is_capture_name_char(chars[name_end]) {
            name_end += 1;
        }
        if name_end == name_start {
            index += 1;
            continue;
        }

        let mut digits_end = name_start;
        while digits_end < name_end && chars[digits_end].is_ascii_digit() {
            digits_end += 1;
        }

        if digits_end > name_start && digits_end < name_end {
            let number: String = chars[name_start..digits_end].iter().collect();
            let suffix: String = chars[digits_end..name_end].iter().collect();
            let shown: String = replacement
                .chars()
                .map(|c| match c {
                    '\n' => '\u{240a}',
                    '\r' => '\u{240d}',
                    '\t' => '\u{2409}',
                    _ => c,
                })
                .collect();
            let message = format!(
                "The numbered capture group `${number}` in the replacement text is \
                 ambiguous.\nhint: Use curly braces to disambiguate it \
                 `${{{number}}}{suffix}`.\n{shown}\n{space}{carets}",
                space = " ".repeat(name_start),
                carets = "^".repeat(name_end - name_start),
            );
            return Err(Failure::AmbiguousReplacement(message));
        }

        index = name_end;
    }

    Ok(())
}

/// Unescapes a regex-mode replacement string.
///
/// Supported one-character escapes are `\n`, `\r`, `\t`, `\\`, `\'`, and
/// `\"`; `\x` takes two hexadecimal digits and `\u` takes four. Unknown
/// or malformed escapes are left intact. For compatibility with the
/// observable behaviour of the tool being reproduced, a successful `\x…`
/// or `\u…` escape also discards the single character following the digits.
fn unescape_replacement(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    let mut chars = input.chars().peekable();

    while let Some(c) = chars.next() {
        if c != '\\' {
            output.push(c);
            continue;
        }

        let Some(escaped) = chars.next() else {
            output.push('\\');
            break;
        };

        match escaped {
            'n' => output.push('\n'),
            'r' => output.push('\r'),
            't' => output.push('\t'),
            '\\' => output.push('\\'),
            '\'' => output.push('\''),
            '"' => output.push('"'),
            'x' | 'u' => {
                let digit_count = if escaped == 'x' { 2 } else { 4 };
                let mut probe = chars.clone();
                let mut value: u32 = 0;
                let mut valid = true;
                for _ in 0..digit_count {
                    match probe.next().and_then(|digit| digit.to_digit(16)) {
                        Some(digit) => value = value * 16 + digit,
                        None => {
                            valid = false;
                            break;
                        }
                    }
                }

                match valid.then(|| char::from_u32(value)).flatten() {
                    Some(decoded) => {
                        for _ in 0..digit_count {
                            chars.next();
                        }
                        // Compatibility quirk: one trailing character is
                        // swallowed after a successful hex/unicode escape.
                        chars.next();
                        output.push(decoded);
                    }
                    None => {
                        output.push('\\');
                        output.push(escaped);
                    }
                }
            }
            other => {
                output.push('\\');
                output.push(other);
            }
        }
    }

    output
}

