// Replacer
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, Default)]
struct FlagSettings {
    case_insensitive: bool,
    dot_matches_new_line: bool,
    multi_line: bool,
    whole_word: bool,
}

fn analyse_flags(flags: Option<&str>) -> FlagSettings {
    let flags = flags.unwrap_or("");
    let whole_word = flags.contains('w');

    // Settings controlled by `i`/`c` and `s` are reset by a later `w` flag;
    // only the text after the last `w` contributes to those two settings.
    let after_last_word_flag = flags.rsplit('w').next().unwrap_or("");

    let mut case_insensitive = false;
    for flag in after_last_word_flag.chars() {
        match flag {
            'i' => case_insensitive = true,
            'c' => case_insensitive = false,
            _ => {}
        }
    }

    FlagSettings {
        case_insensitive,
        dot_matches_new_line: after_last_word_flag.contains('s'),
        multi_line: !flags.contains('e')
            && !whole_word
            && (!flags.contains('s') || flags.contains('m')),
        whole_word,
    }
}

struct Replacer {
    expression: regex::bytes::Regex,
    replacement: Vec<u8>,
    literal_replacement: bool,
    limit: usize,
}

impl Replacer {
    fn new(
        find: &str,
        replacement: &str,
        fixed_strings: bool,
        flags: Option<&str>,
        limit: usize,
    ) -> Outcome<Self> {
        if !fixed_strings {
            validate_replacement(replacement)?;
        }

        let settings = analyse_flags(flags);
        let pattern = if fixed_strings {
            regex::escape(find)
        } else {
            find.to_owned()
        };
        let pattern = if settings.whole_word {
            format!(r"\b{pattern}\b")
        } else {
            pattern
        };

        let mut builder = regex::bytes::RegexBuilder::new(&pattern);
        builder
            .case_insensitive(settings.case_insensitive)
            .dot_matches_new_line(settings.dot_matches_new_line)
            .multi_line(settings.multi_line);
        let expression = builder.build().map_err(Failure::InvalidRegex)?;

        let replacement = if fixed_strings {
            replacement.as_bytes().to_vec()
        } else {
            unescape_replacement(replacement).into_bytes()
        };

        Ok(Self {
            expression,
            replacement,
            literal_replacement: fixed_strings,
            limit,
        })
    }

    fn replace(&self, content: &[u8]) -> Vec<u8> {
        if self.literal_replacement {
            self.expression
                .replacen(
                    content,
                    self.limit,
                    regex::bytes::NoExpand(&self.replacement),
                )
                .into_owned()
        } else {
            self.expression
                .replacen(content, self.limit, self.replacement.as_slice())
                .into_owned()
        }
    }
}

// ---------------------------------------------------------------------------
// Inputs
// ---------------------------------------------------------------------------

struct FileDocument {
    path: PathBuf,
    content: Vec<u8>,
    permissions: Permissions,
}

enum Documents {
    Stdin(Vec<u8>),
    Files(Vec<FileDocument>),
}

fn system_page_size() -> usize {
    let size = unsafe { libc::sysconf(libc::_SC_PAGESIZE) };
    if size > 0 {
        size as usize
    } else {
        4096
    }
}

/// Reads a file through a memory mapping, preserving the operating-system
/// errors that mapping such special files as directories and devices yields.
fn read_file_mapped(path: &Path) -> Outcome<FileDocument> {
    let file = File::open(path)?;
    let metadata = file.metadata()?;
    let permissions = metadata.permissions();
    let size = usize::try_from(metadata.len())
        .map_err(|_| io::Error::new(io::ErrorKind::InvalidInput, "file is too large"))?;
    let mapping_size = if size == 0 { system_page_size() } else { size };

    let pointer = unsafe {
        libc::mmap(
            std::ptr::null_mut(),
            mapping_size,
            libc::PROT_READ,
            libc::MAP_PRIVATE,
            file.as_raw_fd(),
            0,
        )
    };
    if pointer == libc::MAP_FAILED {
        return Err(io::Error::last_os_error().into());
    }

    let content = if size == 0 {
        Vec::new()
    } else {
        unsafe { std::slice::from_raw_parts(pointer as *const u8, size).to_vec() }
    };
    unsafe {
        libc::munmap(pointer, mapping_size);
    }

    Ok(FileDocument {
        path: path.to_owned(),
        content,
        permissions,
    })
}

fn load_documents(files: &[PathBuf]) -> Outcome<Documents> {
    if files.is_empty() {
        let mut content = Vec::new();
        io::stdin().lock().read_to_end(&mut content)?;
        return Ok(Documents::Stdin(content));
    }

    for path in files {
        if !path.exists() {
            return Err(Failure::InvalidPath(path.clone()));
        }
    }

    let mut documents = Vec::with_capacity(files.len());
    for path in files {
        documents.push(read_file_mapped(path)?);
    }
    Ok(Documents::Files(documents))
}

// ---------------------------------------------------------------------------
// Processing
// ---------------------------------------------------------------------------

fn rewrite_in_place(document: &FileDocument, replacer: &Replacer) -> Outcome<()> {
    let replaced = replacer.replace(&document.content);
    let canonical = fs::canonicalize(&document.path)?;
    let directory = canonical.parent().unwrap_or_else(|| Path::new("/"));

    let mut temporary = tempfile::NamedTempFile::new_in(directory)?;
    temporary
        .as_file()
        .set_permissions(document.permissions.clone())?;
    temporary.write_all(&replaced)?;
    temporary
        .persist(&canonical)
        .map_err(Failure::MoveFile)?;
    Ok(())
}

fn process(documents: Documents, replacer: &Replacer, preview: bool) -> Outcome<()> {
    match documents {
        Documents::Stdin(content) => {
            let stdout = io::stdout();
            let mut output = stdout.lock();
            output.write_all(&replacer.replace(&content))?;
            Ok(())
        }
        Documents::Files(documents) => {
            if !preview {
                let mut failures = Vec::new();
                for document in &documents {
                    if let Err(error) = rewrite_in_place(document, replacer) {
                        failures.push((document.path.clone(), error));
                    }
                }
                if failures.is_empty() {
                    Ok(())
                } else {
                    Err(Failure::FailedProcessing(failures))
                }
            } else {
                let show_headers = documents.len() > 1;
                let stdout = io::stdout();
                let mut output = stdout.lock();
                for document in &documents {
                    if show_headers {
                        writeln!(output, "----- FILE {} -----", document.path.display())?;
                    }
                    output.write_all(&replacer.replace(&document.content))?;
                }
                Ok(())
            }
        }
    }
}

fn run(options: Options) -> Outcome<()> {
    let replacer = Replacer::new(
        &options.find,
        &options.replace_with,
        options.fixed_strings,
        options.flags.as_deref(),
        options.max_replacements,
    )?;
    let documents = load_documents(&options.files)?;
    process(documents, &replacer, options.preview)
}

fn main() {
    let options = Options::parse();
    if let Err(error) = run(options) {
        eprintln!("error: {error}");
        std::process::exit(1);
    }
}
