        while digits_end < name_end && chars[digits_end].is_ascii_digit() {
            digits_end += 1;
        }

        if digits_end > name_start && digits_end < name_end {
            let number: String = chars[name_start..digits_end].iter().collect();
            let suffix: String = chars[digits_end..name_end].iter().collect();
