                "The numbered capture group `${number}` in the replacement text is \
                 ambiguous.\nhint: Use curly braces to disambiguate it \
                 `${{{number}}}{suffix}`.\n{shown}\n{space}{carets}",
                space = " ".repeat(name_start),
                carets = "^".repeat(name_end - name_start),
            );
            return Err(Failure::AmbiguousReplacement(message));
        }

        index = name_end;
    }

    Ok(())
