fn is_capture_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_'
}

/// Rejects a replacement such as `$1x`, where a numbered capture is directly
/// followed by further capture-name characters. Without braces the regex
/// replacement parser would read `1x` as a (non-existent) capture name.
fn validate_replacement(replacement: &str) -> Outcome<()> {
    let chars: Vec<char> = replacement.chars().collect();
    let mut index = 0;

    while index < chars.len() {
        if chars[index] != '$' {
            index += 1;
            continue;
        }

        // `$$` is an escaped literal dollar.
        if index + 1 < chars.len() && chars[index + 1] == '$' {
            index += 2;
            continue;
        }

        // `${...}` is unambiguous. A `${` without a closing brace is not a
        // capture reference, so scanning simply moves past the dollar.
        if index + 1 < chars.len() && chars[index + 1] == '{' {
            if let Some(offset) = chars[index + 2..].iter().position(|&c| c == '}') {
                index += 2 + offset + 1;
            } else {
                index += 1;
            }
            continue;
        }

        let name_start = index + 1;
        let mut name_end = name_start;
        while name_end < chars.len() && is_capture_name_char(chars[name_end]) {
            name_end += 1;
        }
        if name_end == name_start {
            index += 1;
            continue;
        }

        let mut digits_end = name_start;
        while digits_end < name_end && chars[digits_end].is_ascii_digit() {
            digits_end += 1;
        }

        if digits_end > name_start && digits_end < name_end {
            let number: String = chars[name_start..digits_end].iter().collect();
            let suffix: String = chars[digits_end..name_end].iter().collect();
            let shown: String = replacement
                .chars()
                .map(|c| match c {
                    '\n' => '\u{240a}',
                    '\r' => '\u{240d}',
                    '\t' => '\u{2409}',
                    _ => c,
