            let message = format!(
                "The numbered capture group `${number}` in the replacement text is \
                 ambiguous.\nhint: Use curly braces to disambiguate it \
                 `${{{number}}}{suffix}`.\n{shown}\n{space}{carets}",
                space = " ".repeat(name_start),
                carets = "^".repeat(name_end - name_start),
            );
            return Err(Failure::AmbiguousReplacement(message));
        }

        index = name_end;
    }

    Ok(())
}

/// Unescapes a regex-mode replacement string.
///
/// Supported one-character escapes are `\n`, `\r`, `\t`, `\\`, `\'`, and
/// `\"`; `\x` takes two hexadecimal digits and `\u` takes four. Unknown
/// or malformed escapes are left intact. For compatibility with the
/// observable behaviour of the tool being reproduced, a successful `\x…`
/// or `\u…` escape also discards the single character following the digits.
fn unescape_replacement(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    let mut chars = input.chars().peekable();

    while let Some(c) = chars.next() {
        if c != '\\' {
            output.push(c);
            continue;
        }

        let Some(escaped) = chars.next() else {
            output.push('\\');
            break;
        };

        match escaped {
            'n' => output.push('\n'),
            'r' => output.push('\r'),
            't' => output.push('\t'),
            '\\' => output.push('\\'),
            '\'' => output.push('\''),
            '"' => output.push('"'),
            'x' | 'u' => {
                let digit_count = if escaped == 'x' { 2 } else { 4 };
                let mut probe = chars.clone();
                let mut value: u32 = 0;
                let mut valid = true;
                for _ in 0..digit_count {
