/// Whether the arguments before the offending token include at least one
/// fully matched argument. An option that is still waiting for a value, such
/// as a trailing `-n`, does not by itself count.
fn has_completed_prior_argument(arguments: &[String]) -> bool {
    let mut completed = false;
    let mut awaiting_value = false;
    let mut after_separator = false;

    for argument in arguments {
        if awaiting_value {
            completed = true;
            awaiting_value = false;
            continue;
        }
        if after_separator {
            completed = true;
            continue;
        }
        if argument == "--" {
            after_separator = true;
            continue;
        }
        if argument == "-" || !argument.starts_with('-') {
            completed = true;
            continue;
        }
        if let Some(long) = argument.strip_prefix("--") {
            let name = long.split('=').next().unwrap_or("");
            match name {
                "max-replacements" | "flags" if !long.contains('=') => awaiting_value = true,
                "preview" | "fixed-strings" | "max-replacements" | "flags" | "help"
                | "version" => completed = true,
                _ => {}
            }
            continue;
        }

        let mut shorthand = argument[1..].chars().peekable();
        while let Some(short) = shorthand.next() {
            match short {
                'p' | 'F' | 'h' | 'V' => completed = true,
                'n' | 'f' => {
                    if shorthand.peek().is_some() {
                        completed = true;
                    } else {
                        awaiting_value = true;
                    }
                    break;
                }
                _ => break,
            }
        }
    }

    completed
}

/// The command-line framework version whose behaviour is being reproduced
/// expanded the usage line for some unknown long arguments into a union of
/// every application argument. Newer versions instead produce a narrower
/// "smart" usage line, so adjust that one class of error before it is shown.
fn adjust_unknown_argument_usage(error: &mut clap::Error) {
    if error.kind() != ErrorKind::UnknownArgument {
        return;
    }
    let Some(invalid_argument) = context_string(error, ContextKind::InvalidArg) else {
        return;
    };
    if !invalid_argument.starts_with("--") {
        return;
    }

    let mut user_arguments = std::env::args_os();
    user_arguments.next();
    let text_arguments: Vec<String> = user_arguments
        .map(|argument| argument.to_string_lossy().into_owned())
        .collect();
    let with_value = format!("{invalid_argument}=");
    let invalid_index = text_arguments
        .iter()
        .position(|argument| argument == invalid_argument || argument.starts_with(&with_value));
    let has_prior_argument = invalid_index.is_some_and(|index| {
        has_completed_prior_argument(&text_arguments[..index])
    });
    let suggested = context_string(error, ContextKind::SuggestedArg);
    let suggested_user_argument = matches!(
        suggested,
        Some("--preview" | "--fixed-strings" | "--max-replacements" | "--flags")
    );
    if !has_prior_argument && !suggested_user_argument {
        return;
    }

    let Some(ContextValue::StyledStr(usage)) = error.get(ContextKind::Usage) else {
        return;
    };
    let usage = format!("{}", usage.ansi());
    // The styled usage begins with a styled heading, followed by the styled
    // binary name. Preserve those two styled spans and replace the rest.
    let mut styled_span_ends = usage.match_indices("\\u{1b}[0m");
    let _ = styled_span_ends.next();
    let Some((second_span_index, second_span)) = styled_span_ends.next() else {
        return;
    };
    let retained = &usage[..second_span_index + second_span.len()];
    // A suggested --help/--version is shown separately, before the union of
    // application arguments, when another argument had already been parsed.
    let adjusted_usage = match suggested {
        Some(builtin @ ("--help" | "--version")) if has_prior_argument => {
            format!("{retained} \\u{1b}[1m{builtin}\\u{1b}[0m {GROUP_USAGE}")
        }
        _ => format!("{retained} {GROUP_USAGE}"),
    };
    error.insert(
        ContextKind::Usage,
        ContextValue::StyledStr(adjusted_usage.into()),
    );
}

