fn context_string<'a>(error: &'a clap::Error, kind: ContextKind) -> Option<&'a str> {
    match error.get(kind) {
        Some(ContextValue::String(value)) => Some(value.as_str()),
        _ => None,
    }
}

fn has_completed_prior_argument(arguments: &[String]) -> bool {
    let mut completed = false;
    let mut awaiting_value = false;
    let mut after_separator = false;

    for argument in arguments {
        if awaiting_value {
            completed = true;
            awaiting_value = false;
            continue;
        }
        if after_separator {
            completed = true;
            continue;
        }
        if argument == "--" {
            after_separator = true;
            continue;
        }
        if argument == "-" || !argument.starts_with('-') {
            completed = true;
            continue;
        }
        if let Some(long) = argument.strip_prefix("--") {
            let name = long.split('=').next().unwrap_or("");
            match name {
                "max-replacements" | "flags" if !long.contains('=') => awaiting_value = true,
                "preview" | "fixed-strings" | "max-replacements" | "flags" | "help"
                | "version" => completed = true,
                _ => {}
            }
            continue;
        }

        let mut shorthand = argument[1..].chars().peekable();
        while let Some(short) = shorthand.next() {
            match short {
                'p' | 'F' | 'h' | 'V' => completed = true,
                'n' | 'f' => {
                    if shorthand.peek().is_some() {
                        completed = true;
                    } else {
                        awaiting_value = true;
                    }
                    break;
                }
                _ => break,
            }
        }
    }

    completed
}

/// For the unexpected-value error (for example `--preview=x`), the older
/// usage calculation only reflected arguments that had been closed by the
/// start of a later token, plus flags and options with attached values. A
/// lone positional or an option taking its value from the next token was
/// still considered open when the offending token was reached.
fn has_finalized_prior_argument(arguments: &[String]) -> bool {
    let mut finalized = false;
    let mut open_argument = false;
    let mut awaiting_value = false;
    let mut after_separator = false;

    for argument in arguments {
        if awaiting_value {
            awaiting_value = false;
            open_argument = true;
            continue;
        }

        if open_argument {
            finalized = true;
            open_argument = false;
        }

        if after_separator {
            open_argument = true;
            continue;
        }
        if argument == "--" {
            after_separator = true;
            continue;
        }
        if argument == "-" || !argument.starts_with('-') {
            open_argument = true;
            continue;
        }
        if let Some(long) = argument.strip_prefix("--") {
            let name = long.split('=').next().unwrap_or("");
            match name {
                "max-replacements" | "flags" if !long.contains('=') => awaiting_value = true,
                "preview" | "fixed-strings" | "max-replacements" | "flags" | "help"
                | "version" => finalized = true,
                _ => {}
            }
            continue;
        }

        let mut shorthand = argument[1..].chars().peekable();
        while let Some(short) = shorthand.next() {
            match short {
                'p' | 'F' | 'h' | 'V' => finalized = true,
                'n' | 'f' => {
                    if shorthand.peek().is_some() {
                        finalized = true;
                    } else {
                        awaiting_value = true;
                    }
                    break;
                }
                _ => break,
            }
        }
    }

    finalized
}

/// The command-line framework version whose behaviour is being reproduced
/// expanded the usage line for some errors into a union of every
/// application argument. Newer versions instead produce a narrower "smart"
/// usage line, so adjust those error classes before they are shown.
fn adjust_argument_usage(error: &mut clap::Error) {
    let Some(invalid_argument) = context_string(error, ContextKind::InvalidArg) else {
        return;
    };
    if !invalid_argument.starts_with("--") {
        return;
    }

    let mut raw_arguments = std::env::args_os();
    raw_arguments.next();
    let text_arguments: Vec<String> = raw_arguments
        .map(|argument| argument.to_string_lossy().into_owned())
        .collect();
    let with_value = format!("{invalid_argument}=");
    let invalid_index = text_arguments
        .iter()
        .position(|argument| argument == invalid_argument || argument.starts_with(&with_value));
    let Some(invalid_index) = invalid_index else {
        return;
    };
    let prior_arguments = &text_arguments[..invalid_index];

    let prefix_argument: Option<&str> = match error.kind() {
        ErrorKind::UnknownArgument => {
            let has_prior_argument = has_completed_prior_argument(prior_arguments);
            let suggested = context_string(error, ContextKind::SuggestedArg);
            let suggested_user_argument = matches!(
                suggested,
                Some("--preview" | "--fixed-strings" | "--max-replacements" | "--flags")
            );
            if !has_prior_argument && !suggested_user_argument {
                return;
            }
            match suggested {
                Some(builtin @ ("--help" | "--version")) if has_prior_argument => Some(builtin),
                _ => None,
            }
        }
        ErrorKind::TooManyValues => {
            if !matches!(
                invalid_argument,
                "--preview" | "--fixed-strings" | "--help" | "--version"
            ) || !has_finalized_prior_argument(prior_arguments)
            {
                return;
            }
            match invalid_argument {
                builtin @ ("--help" | "--version") => Some(builtin),
                _ => None,
            }
        }
        _ => return,
    };

    let Some(ContextValue::StyledStr(usage)) = error.get(ContextKind::Usage) else {
        return;
    };
    let usage = format!("{}", usage.ansi());
    // The styled usage begins with a styled heading, followed by the styled
    // binary name. Preserve those two styled spans and replace the rest.
    let mut styled_span_ends = usage.match_indices("\u{1b}[0m");
    let _ = styled_span_ends.next();
    let Some((second_span_index, second_span)) = styled_span_ends.next() else {
        return;
